from io import StringIO
def task_func(url, table_id):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP error occurred: {e}")
    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")
    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()
    header_row = rows[0].find_all('th')
    headers = [th.get_text(strip=True) for th in header_row] if header_row else None
    data = []
    for row in rows:
        cols = row.find_all('td')
        if cols:
            data.append([col.get_text(strip=True) for col in cols])
    df = pd.DataFrame(data, columns=headers)
    return df

