from PIL import Image
import io
def task_func(url):
    if not isinstance(url, str) or not url:
        raise ValueError("URL is invalid or empty.")
    try:
        response = requests.get(url, timeout=5)
        if response.status_code not in range(200, 300):
            raise ValueError(f"HTTP request failed with status code {response.status_code}.")
        image_bytes = response.content
        try:
            image = Image.open(io.BytesIO(image_bytes))
        except Exception:
            raise ValueError("The fetched content is not a valid image format.")
    except requests.exceptions.Timeout:
        raise ValueError("Request timed out after 5 seconds.")
    except requests.exceptions.RequestException as e:
        raise ValueError(f"Failed to fetch URL: {e}")
    return image

import requests
from pathlib import Path
import zipfile

DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    if not url or not filename:
        return ("Error: URL and filename must be non-empty.", [])
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        response = requests.get(url, stream=True)
        response.raise_for_status()
        zip_path = DOWNLOAD_DIR / filename
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except Exception as e:
        return (f"Error: Network or file download issue: {e}", [])
    try:
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
        filenames = [f.name for f in ZIP_DIR.iterdir()]
        return ("Success", filenames)
    except Exception as e:
        return (f"Error: File extraction issue: {e}", [])

