import requests
from pathlib import Path
import zipfile

DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    if not url or not filename:
        return ("Error: URL and filename must be non-empty.", [])
    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()
    except requests.RequestException as e:
        return (f"Error: Failed to download file - {e}", [])
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = DOWNLOAD_DIR / filename
    try:
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except IOError as e:
        return (f"Error: Failed to save file - {e}", [])
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
    except (zipfile.BadZipFile, IOError) as e:
        return (f"Error: Failed to extract zip file - {e}", [])
    extracted_files = [str(f.relative_to(ZIP_DIR)) for f in ZIP_DIR.iterdir() if f.is_file()]
    return ("Success", extracted_files)

import requests
import pandas as pd
import matplotlib.pyplot as plt

def task_func(api_url):
    if not isinstance(api_url, str):
        raise TypeError("api_url must be a string.")

    try:
        response = requests.get(api_url)
        response.raise_for_status()
        data = response.json()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"API request failed: {e}")

    if not data:
