    except requests.RequestException as e:
        raise ValueError(f"Failed to fetch CSV from URL: {e}")
    try:
        df = pd.read_csv(StringIO(response.text))
    except Exception as e:
        raise ValueError(f"Failed to parse CSV data: {e}")
    if sort_by_column not in df.columns:
        raise ValueError(f"Column '{sort_by_column}' not found in CSV data.")
    return df.sort_values(by=sort_by_column).reset_index(drop=True)

